export default {"html":"<p data-line=\"0\" class=\"code-line\">This article is part of the <a href=\"https://adventar.org/calendars/7114\" target=\"_blank\" rel=\"noopener noreferrer\">Ionic Framework / Capacitor / Stencil Advent Calendar 2021</a>.</p>\n<hr data-line=\"2\" class=\"code-line\">\n<p data-line=\"4\" class=\"code-line\">When a request fails, showing a Toast with code like the following is often enough:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"6\"><span class=\"line\"><span style=\"color:#E1E4E8\">async </span><span style=\"color:#B392F0\">getData</span><span style=\"color:#E1E4E8\">(): Observable</span><span style=\"color:#F97583\">&lt;</span><span style=\"color:#E1E4E8\">Type</span><span style=\"color:#F97583\">&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  return this.httpClient.get&lt;Type&gt;(url)</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    .pipe(</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">      catchError</span><span style=\"color:#E1E4E8\">((</span><span style=\"color:#FFAB70\">e</span><span style=\"color:#E1E4E8\">) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">        this</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">toastController</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">create</span><span style=\"color:#E1E4E8\">({ </span><span style=\"color:#FFAB70\">message</span><span style=\"color:#F97583\">:</span><span style=\"color:#E1E4E8\"> /.../, </span><span style=\"color:#FFAB70\">duration</span><span style=\"color:#F97583\">:</span><span style=\"color:#79B8FF\"> 3000</span><span style=\"color:#E1E4E8\"> }).</span><span style=\"color:#B392F0\">then</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">d</span><span style=\"color:#F97583\"> =&gt;</span><span style=\"color:#E1E4E8\"> d.</span><span style=\"color:#B392F0\">present</span><span style=\"color:#E1E4E8\">());</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">        return</span><span style=\"color:#B392F0\"> throwError</span><span style=\"color:#E1E4E8\">(() </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#B392F0\"> e</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      })</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    )</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"18\" class=\"code-line\">In real projects, though, you sometimes want to show an alert instead of a quick Toast. Something like this:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"20\"><span class=\"line\"><span style=\"color:#E1E4E8\">async </span><span style=\"color:#B392F0\">getData</span><span style=\"color:#E1E4E8\">(): Observable</span><span style=\"color:#F97583\">&lt;</span><span style=\"color:#E1E4E8\">Type</span><span style=\"color:#F97583\">&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  return this.httpClient.get&lt;Type&gt;(url)</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    .pipe(</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">      catchError</span><span style=\"color:#E1E4E8\">((</span><span style=\"color:#FFAB70\">e</span><span style=\"color:#E1E4E8\">) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">        this</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">alertController</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">create</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">          header</span><span style=\"color:#F97583\">:</span><span style=\"color:#9ECBFF\"> 'Error'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">          message</span><span style=\"color:#F97583\">:</span><span style=\"color:#9ECBFF\"> 'The error details go here'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">          buttons</span><span style=\"color:#F97583\">:</span><span style=\"color:#E1E4E8\"> [</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">            {</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">              text</span><span style=\"color:#F97583\">:</span><span style=\"color:#9ECBFF\"> 'Close'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">            },</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">          ],</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">        }).</span><span style=\"color:#B392F0\">then</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">d</span><span style=\"color:#F97583\"> =&gt;</span><span style=\"color:#E1E4E8\"> d.</span><span style=\"color:#B392F0\">present</span><span style=\"color:#E1E4E8\">());</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">        return</span><span style=\"color:#B392F0\"> throwError</span><span style=\"color:#E1E4E8\">(() </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#B392F0\"> e</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      })</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    )</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"40\" class=\"code-line\">However, this has one big problem: the alert is handled asynchronously. Specifically, the error is thrown before the user taps Close on the alert, so processing finishes too early. For example, if you write the page component like this, you have a problem:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"42\"><span class=\"line\"><span style=\"color:#B392F0\">getData</span><span style=\"color:#E1E4E8\">().</span><span style=\"color:#B392F0\">subscribe</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  next</span><span style=\"color:#E1E4E8\">: () </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> { </span><span style=\"color:#9ECBFF\">/</span><span style=\"color:#79B8FF\">..</span><span style=\"color:#9ECBFF\">/</span><span style=\"color:#E1E4E8\"> },</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  error</span><span style=\"color:#E1E4E8\">: () </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">    // Close the modal because the operation failed</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    this</span><span style=\"color:#E1E4E8\">.modalController.</span><span style=\"color:#B392F0\">dismiss</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  },</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"52\" class=\"code-line\">When this runs, the error is thrown before the alert is dismissed, so the modal closes. When you want to “handle the error synchronously,” write it like this instead of the code above:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"55\"><span class=\"line\"><span style=\"color:#E1E4E8\">async </span><span style=\"color:#B392F0\">getData</span><span style=\"color:#E1E4E8\">(): Observable</span><span style=\"color:#F97583\">&lt;</span><span style=\"color:#E1E4E8\">Type</span><span style=\"color:#F97583\">&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  return this.httpClient.get&lt;Type&gt;(url)</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    .pipe(</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">      catchError</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">error</span><span style=\"color:#F97583\"> =&gt;</span><span style=\"color:#B392F0\"> from</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#F97583\">new</span><span style=\"color:#79B8FF\"> Promise</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#F97583\">async</span><span style=\"color:#E1E4E8\"> (</span><span style=\"color:#FFAB70\">resolve</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#FFAB70\">reject</span><span style=\"color:#E1E4E8\">) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">        const</span><span style=\"color:#79B8FF\"> alert</span><span style=\"color:#F97583\"> =</span><span style=\"color:#F97583\"> await</span><span style=\"color:#79B8FF\"> this</span><span style=\"color:#E1E4E8\">.alertController.</span><span style=\"color:#B392F0\">create</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">          header: </span><span style=\"color:#9ECBFF\">'Error'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">          message: </span><span style=\"color:#9ECBFF\">'The error details go here'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">          buttons: [</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">            {</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">              text: </span><span style=\"color:#9ECBFF\">'Close'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">              handler</span><span style=\"color:#E1E4E8\">: () </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#B392F0\"> reject</span><span style=\"color:#E1E4E8\">(error),</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">            },</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">          ],</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">        });</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">        return</span><span style=\"color:#F97583\"> await</span><span style=\"color:#E1E4E8\"> alert.</span><span style=\"color:#B392F0\">present</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      }).</span><span style=\"color:#B392F0\">then</span><span style=\"color:#E1E4E8\">(() </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#79B8FF\"> undefined</span><span style=\"color:#E1E4E8\">))),</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    )</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"76\" class=\"code-line\">To receive <code>catchError</code> as an Observable, convert the Promise with <code>from()</code>. You can write freely inside the Promise, but keep two things in mind. First, because this is error handling, make sure to <code>reject</code>. In practice, I <code>reject</code> inside the handler. Second, you need to chain <code>.then()</code> on the Promise itself. Without that, the type becomes <code>unknown</code> and you cannot handle types correctly.</p>\n<p data-line=\"78\" class=\"code-line\">I received advice on this from <a href=\"https://twitter.com/laco2net/status/1470683811231178754\" target=\"_blank\" rel=\"noopener noreferrer\">laco of Japan Angular User Group</a>. Thank you very much!!</p>\n<p data-line=\"80\" class=\"code-line\">See you next time.</p>\n","headings":[]} as const;
